INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (598, 1, '누락된 PV 의 UUID', '`/tmp/vgs_warn.log` 는 `vgs` 실행 때 나온 출력입니다. 경고에 **찾을 수 없는 장치의 UUID** 가 나옵니다. 이 UUID 를 한 번만 `/tmp/missing_uuid.txt` 에 저장하세요. (UUID 만)', '`uuid` 바로 뒤의 문자열이고 끝의 마침표는 UUID 가 아닙니다. 첫 경고 줄에서 뽑으세요.', 'cat /tmp/vgs_warn.log
grep -m1 ''with uuid'' /tmp/vgs_warn.log | awk ''{print $NF}'' | tr -d ''.'' > /tmp/missing_uuid.txt
cat /tmp/missing_uuid.txt

# 디스크(PV)가 연결되지 않았거나 고장나서 VG 가 완전하지 않다. 케이블·컨트롤러부터 확인하고 PV 가 돌아오면 vgextend --restoremissing 등으로 복구한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/vgs_warn.log <<''EOF''\\n  WARNING: Couldn''t find device with uuid aB3dEf-0000-1111-2222-3333-4444-5555Gh.\\n  WARNING: VG vg0 is missing PV aB3dEf-0000-1111-2222-3333-4444-5555Gh (last written to /dev/sdc).\\n  VG  #PV #LV #SN Attr   VSize   VFree\\n  vg0   3   2   0 wz-pn- 299.99g 129.99g\\nEOF\\ncat > /tmp/lvs_state.log <<''EOF''\\n  LV   VG  Attr       LSize\\n  data vg0 -wi-------  150.00g\\n  logs vg0 -wi-ao----   20.00g\\nEOF\\ncat > /tmp/boot_md.log <<''EOF''\\nPersonalities : [raid1]\\nmd0 : active (auto-read-only) raid1 sdb1[0]\\n      104792064 blocks super 1.2 [2/1] [U_]\\n      bitmap: 1/1 pages [4KB], 65536KB chunk\\n\\nunused devices: <none>\\nEOF\\ncat > /tmp/nfs_hang.log <<''EOF''\\n$ df -h\\n(응답 없이 멈춤. Ctrl-C 로 중단)\\n$ mount | grep nfs\\nnfs01.example.com:/data on /mnt/data type nfs4 (rw,relatime,vers=4.2,hard,timeo=600,retrans=2,sec=sys)\\n$ dmesg | tail -2\\nnfs: server nfs01.example.com not responding, still trying\\nnfs: server nfs01.example.com not responding, still trying\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/missing_uuid.txt)\\" = \\"aB3dEf-0000-1111-2222-3333-4444-5555Gh\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "UUID 가 맞다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/missing_uuid.txt)\\" = \\"aB3dEf-0000-1111-2222-3333-4444-5555Gh\\" ]"]}]', '[{"title": "LVM 복구", "url": "https://access.redhat.com/documentation/en-us/red_hat_enterprise_linux/9/html/configuring_and_managing_logical_volumes/index"}, {"title": "mdadm 문서", "url": "https://raid.wiki.kernel.org/index.php/A_guide_to_mdadm"}]'),
  (598, 2, 'VG 속성 읽기', '같은 출력의 `Attr` 열 `wz-pn-` 은 VG 의 상태를 글자별로 나타냅니다. **네 번째 글자 `p`** 는 **partial**(일부 PV 누락)을 뜻합니다. `VG` 의 **PV 개수(`#PV`)와 LV 개수(`#LV`)** 를 각각 `/tmp/pv.txt`, `/tmp/lv.txt` 에 숫자만 저장하세요.', '`vg0` 로 시작하는 줄에서 두 번째, 세 번째 칸입니다.', 'grep ''^  vg0'' /tmp/vgs_warn.log
grep ''^  vg0'' /tmp/vgs_warn.log | awk ''{print $2}'' > /tmp/pv.txt
grep ''^  vg0'' /tmp/vgs_warn.log | awk ''{print $3}'' > /tmp/lv.txt
cat /tmp/pv.txt /tmp/lv.txt

# 3 개의 PV 중 하나가 없다. VG 가 partial 이면 LV 활성화가 거부되거나 데이터 일부를 읽지 못할 수 있다. 쓰기 전에 원인부터 파악한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/vgs_warn.log <<''EOF''\\n  WARNING: Couldn''t find device with uuid aB3dEf-0000-1111-2222-3333-4444-5555Gh.\\n  WARNING: VG vg0 is missing PV aB3dEf-0000-1111-2222-3333-4444-5555Gh (last written to /dev/sdc).\\n  VG  #PV #LV #SN Attr   VSize   VFree\\n  vg0   3   2   0 wz-pn- 299.99g 129.99g\\nEOF\\ncat > /tmp/lvs_state.log <<''EOF''\\n  LV   VG  Attr       LSize\\n  data vg0 -wi-------  150.00g\\n  logs vg0 -wi-ao----   20.00g\\nEOF\\ncat > /tmp/boot_md.log <<''EOF''\\nPersonalities : [raid1]\\nmd0 : active (auto-read-only) raid1 sdb1[0]\\n      104792064 blocks super 1.2 [2/1] [U_]\\n      bitmap: 1/1 pages [4KB], 65536KB chunk\\n\\nunused devices: <none>\\nEOF\\ncat > /tmp/nfs_hang.log <<''EOF''\\n$ df -h\\n(응답 없이 멈춤. Ctrl-C 로 중단)\\n$ mount | grep nfs\\nnfs01.example.com:/data on /mnt/data type nfs4 (rw,relatime,vers=4.2,hard,timeo=600,retrans=2,sec=sys)\\n$ dmesg | tail -2\\nnfs: server nfs01.example.com not responding, still trying\\nnfs: server nfs01.example.com not responding, still trying\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/pv.txt)\\" = 3 ] ) && ( [ \\"$(cat /tmp/lv.txt)\\" = 2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "PV 가 3 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/pv.txt)\\" = 3 ]"]}, {"label": "LV 가 2 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/lv.txt)\\" = 2 ]"]}]', '[{"title": "LVM 복구", "url": "https://access.redhat.com/documentation/en-us/red_hat_enterprise_linux/9/html/configuring_and_managing_logical_volumes/index"}, {"title": "mdadm 문서", "url": "https://raid.wiki.kernel.org/index.php/A_guide_to_mdadm"}]'),
  (598, 3, '활성화되지 않은 LV', '`/tmp/lvs_state.log` 는 `lvs` 출력입니다. `Attr` 의 **다섯 번째 글자가 `a`** 이면 활성(active)이고 `-` 이면 비활성입니다. **비활성인 LV 의 이름**을 `/tmp/inactive.txt` 에 저장하세요.', '다섯 번째 글자가 `a` 가 아닌 LV 를 찾으세요. 헤더 줄은 제외합니다.', 'cat /tmp/lvs_state.log
awk ''NR>1 && substr($3,5,1) != "a" {print $1}'' /tmp/lvs_state.log > /tmp/inactive.txt
cat /tmp/inactive.txt

# data LV 는 활성화되지 않아 마운트할 수 없다. 원인(PV 누락 등)을 해결한 뒤 활성화한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/vgs_warn.log <<''EOF''\\n  WARNING: Couldn''t find device with uuid aB3dEf-0000-1111-2222-3333-4444-5555Gh.\\n  WARNING: VG vg0 is missing PV aB3dEf-0000-1111-2222-3333-4444-5555Gh (last written to /dev/sdc).\\n  VG  #PV #LV #SN Attr   VSize   VFree\\n  vg0   3   2   0 wz-pn- 299.99g 129.99g\\nEOF\\ncat > /tmp/lvs_state.log <<''EOF''\\n  LV   VG  Attr       LSize\\n  data vg0 -wi-------  150.00g\\n  logs vg0 -wi-ao----   20.00g\\nEOF\\ncat > /tmp/boot_md.log <<''EOF''\\nPersonalities : [raid1]\\nmd0 : active (auto-read-only) raid1 sdb1[0]\\n      104792064 blocks super 1.2 [2/1] [U_]\\n      bitmap: 1/1 pages [4KB], 65536KB chunk\\n\\nunused devices: <none>\\nEOF\\ncat > /tmp/nfs_hang.log <<''EOF''\\n$ df -h\\n(응답 없이 멈춤. Ctrl-C 로 중단)\\n$ mount | grep nfs\\nnfs01.example.com:/data on /mnt/data type nfs4 (rw,relatime,vers=4.2,hard,timeo=600,retrans=2,sec=sys)\\n$ dmesg | tail -2\\nnfs: server nfs01.example.com not responding, still trying\\nnfs: server nfs01.example.com not responding, still trying\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/inactive.txt)\\" = data ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "data 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/inactive.txt)\\" = data ]"]}]', '[{"title": "LVM 복구", "url": "https://access.redhat.com/documentation/en-us/red_hat_enterprise_linux/9/html/configuring_and_managing_logical_volumes/index"}, {"title": "mdadm 문서", "url": "https://raid.wiki.kernel.org/index.php/A_guide_to_mdadm"}]'),
  (598, 4, 'LV 활성화 명령 적기', '`vg0` 의 비활성 LV `data` 를 활성화하는 `lvchange` 명령 한 줄을 `/tmp/activate.txt` 에 적으세요. (샌드박스에는 LVM 이 없어 실행하지 않습니다)', '대상은 `VG명/LV명` 으로 적고, 상태를 바꾸는 옵션은 activate 의 약자입니다.', 'echo ''lvchange -ay vg0/data'' > /tmp/activate.txt
cat /tmp/activate.txt

# VG 가 partial 이면 거부될 수 있다. 데이터 보호가 우선이고 누락 PV 를 먼저 복구한다. 급하면 --activationmode partial 이 있으나 일부 데이터를 읽지 못할 수 있다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/vgs_warn.log <<''EOF''\\n  WARNING: Couldn''t find device with uuid aB3dEf-0000-1111-2222-3333-4444-5555Gh.\\n  WARNING: VG vg0 is missing PV aB3dEf-0000-1111-2222-3333-4444-5555Gh (last written to /dev/sdc).\\n  VG  #PV #LV #SN Attr   VSize   VFree\\n  vg0   3   2   0 wz-pn- 299.99g 129.99g\\nEOF\\ncat > /tmp/lvs_state.log <<''EOF''\\n  LV   VG  Attr       LSize\\n  data vg0 -wi-------  150.00g\\n  logs vg0 -wi-ao----   20.00g\\nEOF\\ncat > /tmp/boot_md.log <<''EOF''\\nPersonalities : [raid1]\\nmd0 : active (auto-read-only) raid1 sdb1[0]\\n      104792064 blocks super 1.2 [2/1] [U_]\\n      bitmap: 1/1 pages [4KB], 65536KB chunk\\n\\nunused devices: <none>\\nEOF\\ncat > /tmp/nfs_hang.log <<''EOF''\\n$ df -h\\n(응답 없이 멈춤. Ctrl-C 로 중단)\\n$ mount | grep nfs\\nnfs01.example.com:/data on /mnt/data type nfs4 (rw,relatime,vers=4.2,hard,timeo=600,retrans=2,sec=sys)\\n$ dmesg | tail -2\\nnfs: server nfs01.example.com not responding, still trying\\nnfs: server nfs01.example.com not responding, still trying\\nEOF\\ntrue"]', '["sh", "-c", "( grep -Eq \\"^[[:space:]]*(sudo )?lvchange( .*)?[ /]vg0/data( .*)?$\\" /tmp/activate.txt ) && ( grep -Eq -- \\"(-a[ ]?y|--activate[= ]y)( |$)\\" /tmp/activate.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "lvchange 명령이고 대상이 vg0/data 다", "cmd": ["sh", "-c", "grep -Eq \\"^[[:space:]]*(sudo )?lvchange( .*)?[ /]vg0/data( .*)?$\\" /tmp/activate.txt"]}, {"label": "활성화(y) 옵션이 있다", "cmd": ["sh", "-c", "grep -Eq -- \\"(-a[ ]?y|--activate[= ]y)( |$)\\" /tmp/activate.txt"]}]', '[{"title": "LVM 복구", "url": "https://access.redhat.com/documentation/en-us/red_hat_enterprise_linux/9/html/configuring_and_managing_logical_volumes/index"}, {"title": "mdadm 문서", "url": "https://raid.wiki.kernel.org/index.php/A_guide_to_mdadm"}]'),
  (598, 5, '성능 저하 RAID', '`/tmp/boot_md.log` 는 서버를 재부팅한 뒤의 `/proc/mdstat` 입니다. 상태 표기 `[2/1] [U_]` 는 디스크 2 개 중 1 개만 동작합니다. **남아 있는 디스크의 이름**(`sdX1` 형태의 이름, 대괄호 번호 제외)을 `/tmp/alive.txt` 에 저장하세요.', '`md0` 줄에서 `raid1` 뒤에 나오는 장치 이름입니다.', 'cat /tmp/boot_md.log
grep ''^md0'' /tmp/boot_md.log | grep -o ''sd[a-z0-9]*\\[[0-9]*\\]'' | cut -d''['' -f1 > /tmp/alive.txt
cat /tmp/alive.txt

# 미러 한쪽이 빠져 중복이 없다. 나머지 한 디스크가 고장나면 데이터를 잃으니 먼저 백업을 확인하고 새 디스크를 --add 해 재구축한다. auto-read-only 는 처음 쓰기 전까지 읽기 전용이라는 뜻이다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/vgs_warn.log <<''EOF''\\n  WARNING: Couldn''t find device with uuid aB3dEf-0000-1111-2222-3333-4444-5555Gh.\\n  WARNING: VG vg0 is missing PV aB3dEf-0000-1111-2222-3333-4444-5555Gh (last written to /dev/sdc).\\n  VG  #PV #LV #SN Attr   VSize   VFree\\n  vg0   3   2   0 wz-pn- 299.99g 129.99g\\nEOF\\ncat > /tmp/lvs_state.log <<''EOF''\\n  LV   VG  Attr       LSize\\n  data vg0 -wi-------  150.00g\\n  logs vg0 -wi-ao----   20.00g\\nEOF\\ncat > /tmp/boot_md.log <<''EOF''\\nPersonalities : [raid1]\\nmd0 : active (auto-read-only) raid1 sdb1[0]\\n      104792064 blocks super 1.2 [2/1] [U_]\\n      bitmap: 1/1 pages [4KB], 65536KB chunk\\n\\nunused devices: <none>\\nEOF\\ncat > /tmp/nfs_hang.log <<''EOF''\\n$ df -h\\n(응답 없이 멈춤. Ctrl-C 로 중단)\\n$ mount | grep nfs\\nnfs01.example.com:/data on /mnt/data type nfs4 (rw,relatime,vers=4.2,hard,timeo=600,retrans=2,sec=sys)\\n$ dmesg | tail -2\\nnfs: server nfs01.example.com not responding, still trying\\nnfs: server nfs01.example.com not responding, still trying\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/alive.txt)\\" = sdb1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "sdb1 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/alive.txt)\\" = sdb1 ]"]}]', '[{"title": "LVM 복구", "url": "https://access.redhat.com/documentation/en-us/red_hat_enterprise_linux/9/html/configuring_and_managing_logical_volumes/index"}, {"title": "mdadm 문서", "url": "https://raid.wiki.kernel.org/index.php/A_guide_to_mdadm"}]'),
  (598, 6, 'NFS 서버가 응답하지 않는 증상', '`/tmp/nfs_hang.log` 는 `df -h` 가 멈추는 서버의 점검 기록입니다. 마운트 옵션 중 **응답이 없을 때 계속 기다리게 하는 옵션**과, 커널이 남긴 **응답 없음 메시지가 몇 줄**인지를 저장하세요.
- `/tmp/opt.txt` : 해당 옵션 (`hard` 또는 `soft` 한 단어)
- `/tmp/msgs.txt` : `not responding` 메시지 줄 수', '마운트 옵션 줄에서 계속 기다리는 쪽을 고르고, `not responding` 이 들어간 줄을 세세요.', 'cat /tmp/nfs_hang.log
grep -o ''hard\\|soft'' /tmp/nfs_hang.log | head -1 > /tmp/opt.txt
grep -c ''not responding'' /tmp/nfs_hang.log > /tmp/msgs.txt
cat /tmp/opt.txt /tmp/msgs.txt

# hard 마운트는 서버가 돌아올 때까지 무한히 재시도해 df·ls 같은 명령까지 멈춘다. 서버·네트워크를 복구하거나 필요하면 lazy 언마운트(umount -l)로 프로세스를 풀어 준다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.log\\ncat > /tmp/vgs_warn.log <<''EOF''\\n  WARNING: Couldn''t find device with uuid aB3dEf-0000-1111-2222-3333-4444-5555Gh.\\n  WARNING: VG vg0 is missing PV aB3dEf-0000-1111-2222-3333-4444-5555Gh (last written to /dev/sdc).\\n  VG  #PV #LV #SN Attr   VSize   VFree\\n  vg0   3   2   0 wz-pn- 299.99g 129.99g\\nEOF\\ncat > /tmp/lvs_state.log <<''EOF''\\n  LV   VG  Attr       LSize\\n  data vg0 -wi-------  150.00g\\n  logs vg0 -wi-ao----   20.00g\\nEOF\\ncat > /tmp/boot_md.log <<''EOF''\\nPersonalities : [raid1]\\nmd0 : active (auto-read-only) raid1 sdb1[0]\\n      104792064 blocks super 1.2 [2/1] [U_]\\n      bitmap: 1/1 pages [4KB], 65536KB chunk\\n\\nunused devices: <none>\\nEOF\\ncat > /tmp/nfs_hang.log <<''EOF''\\n$ df -h\\n(응답 없이 멈춤. Ctrl-C 로 중단)\\n$ mount | grep nfs\\nnfs01.example.com:/data on /mnt/data type nfs4 (rw,relatime,vers=4.2,hard,timeo=600,retrans=2,sec=sys)\\n$ dmesg | tail -2\\nnfs: server nfs01.example.com not responding, still trying\\nnfs: server nfs01.example.com not responding, still trying\\nEOF\\ntrue"]', '["sh", "-c", "( [ \\"$(cat /tmp/opt.txt)\\" = hard ] ) && ( [ \\"$(cat /tmp/msgs.txt)\\" = 2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "hard 다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/opt.txt)\\" = hard ]"]}, {"label": "2 줄이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/msgs.txt)\\" = 2 ]"]}]', '[{"title": "LVM 복구", "url": "https://access.redhat.com/documentation/en-us/red_hat_enterprise_linux/9/html/configuring_and_managing_logical_volumes/index"}, {"title": "mdadm 문서", "url": "https://raid.wiki.kernel.org/index.php/A_guide_to_mdadm"}]'),
  (598, 7, 'partial VG 에서 하지 말아야 할 일', 'VG 에서 PV 하나가 사라져 `partial` 입니다. 데이터를 지키는 관점에서 하지 말아야 할 일은?', '원인을 모르는 채로 구조를 바꾸면 되돌릴 수 없을 수 있습니다.', NULL, NULL, '[]', 'choice', '["케이블과 컨트롤러 연결 상태를 먼저 확인한다", "가능하면 남은 LV 의 데이터를 먼저 백업한다", "원인을 확인하지 않고 누락 PV 를 VG 에서 강제로 제거한다", "누락 PV 가 돌아왔는지 `pvs` 로 확인한다"]', 2, '누락 PV 를 강제로 제거(vgreduce --removemissing)하면 그 PV 에 있던 데이터가 영구히 사라질 수 있습니다. 먼저 연결·장치 인식을 확인하고, 백업을 확보한 뒤 단계적으로 복구합니다.', NULL, NULL, NULL, NULL),
  (598, 8, 'hard 마운트의 대응', 'NFS 서버가 점검 중이라 응답하지 않아 `hard` 마운트를 쓰는 서버의 프로세스들이 멈췄습니다. 가장 알맞은 대응은?', '서버가 돌아오면 재개되는 성질을 이해해야 합니다.', NULL, NULL, '[]', 'choice', '["프로세스를 kill -9 로 모두 종료해도 즉시 사라진다", "NFS 서버를 복구하면 멈춘 프로세스가 이어서 동작한다", "서버를 재부팅하지 않으면 영원히 해결할 수 없다", "마운트 옵션이 hard 라서 서버를 복구해도 소용없다"]', 1, 'hard 마운트는 서버가 돌아오면 요청이 이어져 데이터 무결성이 유지됩니다. D 상태의 프로세스는 kill -9 로도 바로 종료되지 않을 수 있고, 급하면 `umount -f`/`-l` 을 쓰지만 데이터 손실 위험이 있습니다.', NULL, NULL, NULL, NULL),
  (598, 9, 'LV 활성화 옵션', 'LV 를 **활성화(active)** 로 바꾸는 `lvchange` 의 `-a` 옵션 값을 채우세요.', '`-a` 옵션 뒤에 활성화인지 비활성화인지를 한 글자로 적습니다.', NULL, NULL, '[]', 'fill', '["y", "n", "l", "e"]', NULL, '`-ay` 는 활성화, `-an` 은 비활성화입니다. `ly`·`ey` 처럼 `l`(로컬)·`e`(배타)를 앞에 붙이는 형태는 클러스터에서 씁니다.', '[0]', 'lvchange -a{0} vg0/data', NULL, NULL),
  (598, 10, '디스크 장애 때 데이터를 지키는 순서', 'RAID 어레이가 성능 저하 상태가 되고 LV 도 일부 문제가 있습니다. 데이터를 잃지 않도록 하는 순서로 놓으세요. (문제를 파악한 뒤 보호하고 조치하며 마지막에 검증하는 흐름입니다.)', '디스크를 바꾸거나 재구축하는 작업은 그 전에 준비가 끝난 뒤에 합니다.', NULL, NULL, '[]', 'order', '["고장난 디스크를 교체하고 재구축을 진행한다", "교체 전에 남은 데이터를 백업하거나 복제해 확보한다", "교체 전에 어느 디스크·어레이가 문제인지 상태를 확인한다", "재구축이 끝나고 정상인지 확인한다"]', NULL, '상태를 파악하고, 남은 데이터를 먼저 확보한 뒤, 교체와 재구축을 하고, 마지막에 정상 여부를 확인합니다. 재구축 중에는 남은 디스크에 부하가 커서 백업 없이 진행하면 위험합니다.', '[2, 1, 0, 3]', NULL, NULL, NULL);
